import 'package:family_veda/models/member.dart';
import 'package:family_veda/providers/active_member_provider.dart';
import 'package:family_veda/providers/auth_provider.dart';
import 'package:family_veda/providers/core_providers.dart';
import 'package:family_veda/providers/members_provider.dart';
import 'package:family_veda/services/api/auth_api.dart';
import 'package:family_veda/services/api/patient_api.dart';
import 'package:family_veda/services/storage/secure_token_store.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:flutter_test/flutter_test.dart';

class _CountingPatientApi extends Fake implements PatientApi {
  int memberCalls = 0;

  @override
  Future<List<Member>> getMembers() async {
    memberCalls++;
    // A Family Head's list holds the minors too, and a minor can come first.
    return const [
      Member(
        id: 'minor-1',
        displayName: 'Synthetic Minor',
        relationshipLabel: 'Minor',
      ),
      Member(
        id: 'self-1',
        displayName: 'Synthetic Head',
        relationshipLabel: 'Head',
        isSelf: true,
      ),
    ];
  }
}

class _RestoringAuthApi extends Fake implements AuthApi {
  @override
  Future<AuthTokens> refresh(String refreshToken) async => const AuthTokens(
    userId: 'user-1',
    accessToken: 'access',
    refreshToken: 'refresh-2',
    userType: 'FamilyUser',
  );
}

class _FakeTokenStore extends Fake implements TokenStore {
  @override
  Stream<void> get sessionExpirations => const Stream.empty();

  @override
  Future<bool> isCleanupPending() async => false;

  @override
  Future<String?> readRefreshToken() async => 'refresh-1';

  @override
  Future<void> writeTokens({
    required String accessToken,
    required String refreshToken,
  }) async {}
}

void main() {
  test('Member.fromJson reads isSelf and defaults it to false', () {
    final base = {'id': 'm', 'displayName': 'A', 'role': 'Head'};
    expect(Member.fromJson({...base, 'isSelf': true}).isSelf, isTrue);
    expect(Member.fromJson(base).isSelf, isFalse);
  });

  test('preferredMember picks the signed-in user, not the first listed', () {
    const minor = Member(
      id: 'minor-1',
      displayName: 'M',
      relationshipLabel: 'Minor',
    );
    const self = Member(
      id: 'self-1',
      displayName: 'H',
      relationshipLabel: 'Head',
      isSelf: true,
    );
    expect(preferredMember(const [minor, self])?.id, 'self-1');
    expect(preferredMember(const [minor])?.id, 'minor-1');
    expect(preferredMember(const []), isNull);
  });

  test('members are not requested before sign-in finishes, then load and '
      'default to the signed-in user', () async {
    final api = _CountingPatientApi();
    final container = ProviderContainer(
      overrides: [
        patientApiProvider.overrideWithValue(api),
        authProvider.overrideWith(
          (_) => AuthController(
            authApi: _RestoringAuthApi(),
            tokenStore: _FakeTokenStore(),
          ),
        ),
      ],
    );
    addTearDown(container.dispose);
    final subscription = container.listen(activeMemberProvider, (_, _) {});
    addTearDown(subscription.close);

    // Session restore is still in flight: an unauthenticated /families/me would 401.
    expect(container.read(authProvider).status, AuthStatus.loading);
    expect(await container.read(membersProvider.future), isEmpty);
    expect(api.memberCalls, 0);

    await Future<void>.delayed(const Duration(milliseconds: 50));
    expect(container.read(authProvider).status, AuthStatus.authenticated);
    expect((await container.read(membersProvider.future)).length, 2);
    expect(api.memberCalls, 1);
    expect(container.read(activeMemberProvider), 'self-1');
  });
}
